/**
 * pi-agent-core example.
 *
 * Install:
 *   npm i @mariozechner/pi-agent-core @mariozechner/pi-ai typebox self-improving-agent
 */
import { Agent } from "@mariozechner/pi-agent-core";
import { feedbackTools } from "self-improving-agent/pi";

export function buildAgent(systemPrompt: string, model: unknown, getApiKey: () => string) {
  return new Agent({
    initialState: {
      systemPrompt, // unchanged — your own prompt
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      model: model as any,
      thinkingLevel: "high",
      tools: [...feedbackTools], // append the two feedback tools to your existing tools
      messages: [],
    },
    getApiKey,
    toolExecution: "sequential",
  });
}

/**
 * Claude Agent SDK example.
 *
 * Install:
 *   npm i @anthropic-ai/claude-agent-sdk self-improving-agent
 *
 * Run:
 *   SELF_IMPROVING_AGENT_REPO=BerriAI/your-repo \
 *   SELF_IMPROVING_AGENT_GITHUB_TOKEN=ghp_xxx \
 *   tsx examples/claude-agent-sdk.ts "feedback: you keep skipping the env-vars step"
 */
import { query } from "@anthropic-ai/claude-agent-sdk";
import { feedbackMcp } from "self-improving-agent/claude";

const userMessage =
  process.argv.slice(2).join(" ") ||
  "feedback: you keep skipping the env-vars step";

for await (const event of query({
  prompt: userMessage,
  options: {
    ...feedbackMcp(),
    model: "claude-sonnet-4-5",
  },
})) {
  if (event.type === "assistant" && event.message?.content) {
    for (const block of event.message.content) {
      if (block.type === "text") process.stdout.write(block.text);
    }
  }
}
process.stdout.write("\n");

/**
 * Drop-in tools for `@mariozechner/pi-agent-core`.
 *
 * Zero-config usage:
 *
 *   import { feedbackTools, feedbackSkill } from "self-improving-agent/pi";
 *   import { Agent } from "@mariozechner/pi-agent-core";
 *
 *   const agent = new Agent({
 *     initialState: {
 *       systemPrompt: `${myPrompt}\n\n${feedbackSkill}`,
 *       tools: [...myTools, ...feedbackTools],
 *       messages: [],
 *       model,
 *       thinkingLevel: "high",
 *     },
 *     getApiKey,
 *     toolExecution: "sequential",
 *   });
 *
 * Config falls back to env vars (see ./env.ts). For callbacks, use
 * `createFeedbackTools({ onProposed, onApplied, onBeforeApply })`.
 */
import type { AgentTool } from "@mariozechner/pi-agent-core";
import { Type } from "typebox";
import {
  feedbackTools as buildFeedbackTools,
  type FeedbackToolsOptions,
} from "./tools.js";

const WriteParams = Type.Object({
  file: Type.String({ description: "Repo-relative path of the file to change." }),
  originalSnippet: Type.String({
    description: "Exact contiguous substring from the current file. Must appear exactly once.",
  }),
  proposedSnippet: Type.String({ description: "Replacement text for originalSnippet." }),
  reason: Type.String({
    description: "1–3 sentences: what failure mode this fixes and why this diff addresses it.",
  }),
  risk: Type.Union(
    [Type.Literal("low"), Type.Literal("medium"), Type.Literal("high")],
    {
      description: "low = wording/docs · medium = behavior change · high = infra/auth/data.",
    }
  ),
});

const ApplyParams = Type.Object({
  proposalId: Type.String({
    description: "The proposalId returned by a prior write_improvement_proposal call.",
  }),
  userConfirmedInThisMessage: Type.Boolean({
    description:
      "MUST be true. Only set if the user's most recent message is an explicit approval.",
  }),
});

/**
 * Build the two pi-agent-core tools.
 *
 * Use this when you need callbacks (`onProposed`, `onApplied`, `onBeforeApply`)
 * or want to override `repo` / `token` / `cacheDir` / `proposalsDir`.
 */
export function createFeedbackTools(opts: FeedbackToolsOptions = {}): AgentTool[] {
  const fb = buildFeedbackTools(opts);

  const writeTool: AgentTool<typeof WriteParams> = {
    name: fb.writeImprovementProposal.name,
    label: "Write improvement proposal",
    description: fb.writeImprovementProposal.description,
    parameters: WriteParams,
    execute: async (_id, input) => {
      const r = await fb.writeImprovementProposal.execute(input);
      return {
        content: [{ type: "text" as const, text: r.message }],
        details: { proposalId: r.proposalId, risk: input.risk },
      };
    },
  };

  const applyTool: AgentTool<typeof ApplyParams> = {
    name: fb.applyProposal.name,
    label: "Apply proposal",
    description: fb.applyProposal.description,
    parameters: ApplyParams,
    execute: async (_id, input) => {
      const r = await fb.applyProposal.execute(input);
      return {
        content: [{ type: "text" as const, text: r.message }],
        details: { prUrl: r.prUrl, branch: r.branch },
        terminate: true,
      };
    },
  };

  return [writeTool as AgentTool, applyTool as AgentTool];
}

/**
 * Zero-config tool array. Reads `SELF_IMPROVING_AGENT_REPO`,
 * `SELF_IMPROVING_AGENT_GITHUB_TOKEN`, and (optionally)
 * `SELF_IMPROVING_AGENT_CACHE_DIR` / `SELF_IMPROVING_AGENT_PROPOSALS_DIR`
 * from the environment at call time.
 *
 * Spread directly into `tools: [...feedbackTools]` in your Agent state.
 */
export const feedbackTools: AgentTool[] = createFeedbackTools();

export { feedbackSkill } from "./skill.js";

export { feedbackSkill } from "./skill.js";
export {
  feedbackTools,
  writeImprovementProposalSchema,
  applyProposalSchema,
  type FeedbackTool,
  type FeedbackToolsContext,
  type FeedbackToolsOptions,
  type WriteImprovementProposalInput,
  type WriteImprovementProposalResult,
  type ApplyProposalInput,
  type ApplyProposalResult,
} from "./tools.js";
export {
  saveProposal,
  loadProposal,
  type Proposal,
  type SavedProposal,
} from "./proposal.js";
export {
  applyProposal,
  ensureClone,
  type ApplyOptions,
  type ApplyResult,
} from "./apply.js";
export { resolveConfig } from "./env.js";
export type { RepoRef, ResolvedConfig } from "./env.js";

/**
 * Resolve configuration with env-var fallbacks.
 *
 * Recognized vars:
 *   SELF_IMPROVING_AGENT_REPO            "owner/name" of the GitHub repo
 *                                        whose code/prompts the agent can PR
 *   SELF_IMPROVING_AGENT_GITHUB_TOKEN    PAT with contents:write +
 *                                        pull_requests:write on that repo
 *   SELF_IMPROVING_AGENT_PROPOSALS_DIR   where proposal JSON files are saved
 *                                        (default: ./runs/improvements)
 *   SELF_IMPROVING_AGENT_CACHE_DIR       where the lib clones the repo
 *                                        (default: ~/.cache/self-improving-agent/<owner>__<name>)
 *   SELF_IMPROVING_AGENT_BASE_BRANCH     base branch for PRs (default: main)
 */

import os from "node:os";
import path from "node:path";

export interface RepoRef {
  owner: string;
  name: string;
}

export interface ResolvedConfig {
  repo: RepoRef;
  /** May be empty during partial resolution (e.g. building tool descriptions). */
  token: string;
  cacheDir: string;
  proposalsDir: string;
  baseBranch: string;
}

export interface PartialConfigOpts {
  repo?: string | RepoRef;
  token?: string;
  cacheDir?: string;
  proposalsDir?: string;
  baseBranch?: string;
}

export interface ResolveOpts extends PartialConfigOpts {
  /**
   * If true, return placeholders instead of throwing when required vars
   * are missing. Used at construction time to bake whatever we know into
   * the tool description without crashing on import.
   */
  lenient?: boolean;
}

function parseRepo(input: string): RepoRef {
  const m = input.trim().match(/^([^/]+)\/([^/]+?)(?:\.git)?$/);
  if (!m) {
    throw new Error(
      `SELF_IMPROVING_AGENT_REPO must be "owner/name" (got: ${JSON.stringify(input)})`
    );
  }
  return { owner: m[1]!, name: m[2]! };
}

function defaultCacheDir(repo: RepoRef): string {
  const xdgCache =
    process.env.XDG_CACHE_HOME ?? path.join(os.homedir(), ".cache");
  return path.join(
    xdgCache,
    "self-improving-agent",
    `${repo.owner}__${repo.name}`
  );
}

let warnedAboutMissingRepo = false;

/**
 * Resolve the runtime config. Throws on missing required vars unless
 * `lenient: true` is passed (in which case missing fields come back as
 * empty strings / a placeholder repo and the warning fires once).
 */
export function resolveConfig(opts: ResolveOpts = {}): ResolvedConfig {
  const repoInput = opts.repo ?? process.env.SELF_IMPROVING_AGENT_REPO;
  let repo: RepoRef;
  if (!repoInput) {
    if (!opts.lenient) {
      throw new Error(
        "SELF_IMPROVING_AGENT_REPO is required (e.g. 'BerriAI/shin-builder-oss')."
      );
    }
    if (!warnedAboutMissingRepo) {
      warnedAboutMissingRepo = true;
      // eslint-disable-next-line no-console
      console.warn(
        "[self-improving-agent] SELF_IMPROVING_AGENT_REPO is not set. " +
          "Tools will fail when called. Set it to 'owner/name' of the GitHub " +
          "repo the agent should propose PRs against."
      );
    }
    repo = { owner: "OWNER", name: "REPO" };
  } else if (typeof repoInput === "string") {
    repo = parseRepo(repoInput);
  } else {
    repo = repoInput;
  }

  const token = opts.token ?? process.env.SELF_IMPROVING_AGENT_GITHUB_TOKEN ?? "";
  if (!token && !opts.lenient) {
    throw new Error(
      "SELF_IMPROVING_AGENT_GITHUB_TOKEN is required. Use a fine-grained PAT " +
        "with 'contents: write' and 'pull requests: write' on the repo."
    );
  }

  const cacheDir =
    opts.cacheDir ??
    process.env.SELF_IMPROVING_AGENT_CACHE_DIR ??
    defaultCacheDir(repo);

  const proposalsDir =
    opts.proposalsDir ??
    process.env.SELF_IMPROVING_AGENT_PROPOSALS_DIR ??
    "./runs/improvements";

  const baseBranch =
    opts.baseBranch ?? process.env.SELF_IMPROVING_AGENT_BASE_BRANCH ?? "main";

  return { repo, token, cacheDir, proposalsDir, baseBranch };
}

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

/** A single proposed self-improvement diff. */
export interface Proposal {
  /** Repo-relative path of the file to change. */
  file: string;
  /**
   * Exact contiguous substring from the file. Must appear exactly once
   * for `applyProposal` to succeed.
   */
  originalSnippet: string;
  /** Replacement text for `originalSnippet`. */
  proposedSnippet: string;
  /** 1–3 sentences: why this change. */
  reason: string;
  /** "low" = wording/docs · "medium" = behavior · "high" = infra/auth. */
  risk: "low" | "medium" | "high";
}

export interface SavedProposal extends Proposal {
  proposalId: string;
  createdAt: string;
}

/**
 * Persist a proposal to `<dir>/<proposalId>.json` and return the absolute path
 * plus the generated id.
 *
 * The id is short and URL-safe so callers can pass it back to `apply_proposal`
 * without escaping.
 */
export function saveProposal(
  proposal: Proposal,
  dir: string
): { proposalId: string; path: string } {
  fs.mkdirSync(dir, { recursive: true });
  const proposalId = crypto.randomBytes(6).toString("hex");
  const filePath = path.join(dir, `${proposalId}.json`);
  const record: SavedProposal = {
    proposalId,
    createdAt: new Date().toISOString(),
    ...proposal,
  };
  fs.writeFileSync(filePath, JSON.stringify(record, null, 2), "utf-8");
  return { proposalId, path: filePath };
}

/** Load a previously saved proposal by id from `dir`. */
export function loadProposal(dir: string, proposalId: string): SavedProposal {
  if (!/^[a-zA-Z0-9_-]+$/.test(proposalId)) {
    throw new Error(`Invalid proposalId: ${proposalId}`);
  }
  const filePath = path.join(dir, `${proposalId}.json`);
  const raw = fs.readFileSync(filePath, "utf-8");
  const data = JSON.parse(raw) as SavedProposal;
  for (const k of ["file", "originalSnippet", "proposedSnippet", "reason", "risk"] as const) {
    if (typeof data[k] !== "string") {
      throw new Error(`Invalid proposal ${proposalId}: missing ${k}`);
    }
  }
  return data;
}

/**
 * Drop-in custom tools for the Claude Agent SDK
 * (`@anthropic-ai/claude-agent-sdk`).
 *
 * `feedbackTools` is an array of `SdkMcpToolDefinition` objects — the exact
 * shape returned by the SDK's `tool()` helper. They run in-process, just
 * like any other custom tool you build. Mix them with your own tools and
 * bundle once with `createSdkMcpServer`:
 *
 *   import { tool, createSdkMcpServer, query } from "@anthropic-ai/claude-agent-sdk";
 *   import { feedbackTools } from "self-improving-agent/claude";
 *
 *   const server = createSdkMcpServer({
 *     name: "my-agent",
 *     version: "1.0.0",
 *     tools: [...myTools, ...feedbackTools],
 *   });
 *
 *   for await (const _ of query({
 *     prompt,
 *     options: {
 *       mcpServers: { "my-agent": server },
 *       allowedTools: [
 *         "mcp__my-agent__write_improvement_proposal",
 *         "mcp__my-agent__apply_proposal",
 *       ],
 *     },
 *   })) { ... }
 *
 * See https://code.claude.com/docs/en/agent-sdk/custom-tools for the full
 * custom-tool surface (it's all in-process — no external MCP).
 *
 * Config falls back to env vars (see ./env.ts). For callbacks, use
 * `createFeedbackTools({ onProposed, onApplied, onBeforeApply })`.
 */
import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";
import { feedbackTools as buildFeedbackTools, type FeedbackToolsOptions } from "./tools.js";

const SERVER_NAME = "self_improving_agent";
const SERVER_VERSION = "0.5.0";

const writeShape = {
  file: z.string().describe("Repo-relative path of the file to change."),
  originalSnippet: z
    .string()
    .describe("Exact contiguous substring from the current file. Must appear exactly once."),
  proposedSnippet: z.string().describe("Replacement text for originalSnippet."),
  reason: z
    .string()
    .describe("1–3 sentences: what failure mode this fixes and why this diff addresses it."),
  risk: z
    .enum(["low", "medium", "high"])
    .describe("low = wording/docs · medium = behavior change · high = infra/auth/data."),
};

const applyShape = {
  proposalId: z
    .string()
    .describe("The proposalId returned by a prior write_improvement_proposal call."),
  userConfirmedInThisMessage: z
    .boolean()
    .describe(
      "MUST be true. Only set if the user's most recent message is an explicit approval."
    ),
};

/**
 * Build the two feedback tools as `SdkMcpToolDefinition[]`.
 *
 * Wrap with `createSdkMcpServer({ name, tools })` and pass the result into
 * `query({ options: { mcpServers: { ... } } })`.
 *
 * Use this factory when you need callbacks (`onProposed`, `onApplied`,
 * `onBeforeApply`) or want to override `repoRoot` / `proposalsDir`.
 */
export function createFeedbackTools(opts: FeedbackToolsOptions = {}) {
  const fb = buildFeedbackTools(opts);

  const writeTool = tool(
    fb.writeImprovementProposal.name,
    fb.writeImprovementProposal.description,
    writeShape,
    async (args) => {
      const result = await fb.writeImprovementProposal.execute(args);
      return { content: [{ type: "text", text: result.message }] };
    }
  );

  const applyTool = tool(
    fb.applyProposal.name,
    fb.applyProposal.description,
    applyShape,
    async (args) => {
      const result = await fb.applyProposal.execute(args);
      return { content: [{ type: "text", text: result.message }] };
    }
  );

  return [writeTool, applyTool];
}

/**
 * Zero-config tools array. Reads `SELF_IMPROVING_AGENT_REPO_ROOT` and
 * `SELF_IMPROVING_AGENT_PROPOSALS_DIR` from the environment at call time.
 *
 *   const sia = createSdkMcpServer({ name: "sia", tools: feedbackTools });
 */
export const feedbackTools = createFeedbackTools();

/**
 * One-liner integration. Returns `{ mcpServers, allowedTools }` ready
 * to spread into your `query({ options })`:
 *
 *   import { query } from "@anthropic-ai/claude-agent-sdk";
 *   import { feedbackMcp } from "self-improving-agent/claude";
 *
 *   await query({ prompt, options: feedbackMcp() });
 *
 * If you already have your own `mcpServers` / `allowedTools`, merge:
 *
 *   const fb = feedbackMcp();
 *   await query({
 *     prompt,
 *     options: {
 *       mcpServers:  { ...myServers,  ...fb.mcpServers  },
 *       allowedTools: [ ...myAllowed, ...fb.allowedTools ],
 *     },
 *   });
 *
 * The Claude SDK addresses custom tools as `mcp__{server}__{tool}`, so the
 * MCP wrapping and tool-name prefixing are unavoidable — this helper just
 * hides them.
 */
export function feedbackMcp(opts: FeedbackToolsOptions = {}) {
  const tools = createFeedbackTools(opts);
  const server = createSdkMcpServer({
    name: SERVER_NAME,
    version: SERVER_VERSION,
    tools,
  });
  return {
    mcpServers: { [SERVER_NAME]: server },
    allowedTools: [
      `mcp__${SERVER_NAME}__write_improvement_proposal`,
      `mcp__${SERVER_NAME}__apply_proposal`,
    ],
  };
}

export { feedbackSkill } from "./skill.js";

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import type { Proposal } from "./proposal.js";
import type { RepoRef } from "./env.js";

export interface ApplyResult {
  branch: string;
  prUrl: string;
  commitSha: string;
}

export interface ApplyOptions {
  repo: RepoRef;
  /** PAT used to clone, push, and open the PR. */
  token: string;
  /** Where the lib keeps a working clone of the repo. */
  cacheDir: string;
  /** Base branch for the PR. Default: "main". */
  baseBranch?: string;
  /** Branch name prefix. Default: "improvement". */
  branchPrefix?: string;
  /** PR title. Default: "Self-improve: <file>". */
  prTitle?: string;
  /** PR body. Default: an auto-generated diff summary. */
  prBody?: string;
  /** Open the PR as a draft. Default: true. */
  draft?: boolean;
  /** Custom commit message. Default: derived from `proposal.reason`. */
  commitMessage?: string;
  /** Override the GitHub API base. Default: https://api.github.com. */
  apiBase?: string;
}

function execGit(args: string[], cwd?: string): string {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

/**
 * Run a git command with one-shot HTTP auth. Uses HTTP Basic with the
 * `x-access-token` username convention so it works for both classic and
 * fine-grained PATs. The token rides in argv for the lifetime of the
 * call only — never persisted to `.git/config`.
 */
function execGitWithAuth(args: string[], token: string, cwd?: string): string {
  const basic = Buffer.from(`x-access-token:${token}`, "utf-8").toString(
    "base64"
  );
  return execGit(
    ["-c", `http.extraheader=AUTHORIZATION: Basic ${basic}`, ...args],
    cwd
  );
}

/**
 * Ensure the cache clone exists and is on a clean copy of `baseBranch`.
 * Idempotent: clones if missing, otherwise fetches + resets to origin.
 */
export function ensureClone(opts: {
  repo: RepoRef;
  token: string;
  cacheDir: string;
  baseBranch: string;
}): void {
  const remoteUrl = `https://github.com/${opts.repo.owner}/${opts.repo.name}.git`;

  if (!fs.existsSync(path.join(opts.cacheDir, ".git"))) {
    fs.mkdirSync(path.dirname(opts.cacheDir), { recursive: true });
    execGitWithAuth(
      ["clone", "--depth", "50", remoteUrl, opts.cacheDir],
      opts.token
    );
    return;
  }

  // Refresh existing clone. Discard any leftover branch/commits from prior runs.
  execGitWithAuth(["fetch", "--prune", "origin"], opts.token, opts.cacheDir);
  // If a previous run left us on a feature branch, hop back to base.
  try {
    execGit(["checkout", opts.baseBranch], opts.cacheDir);
  } catch {
    execGit(
      ["checkout", "-B", opts.baseBranch, `origin/${opts.baseBranch}`],
      opts.cacheDir
    );
  }
  execGit(
    ["reset", "--hard", `origin/${opts.baseBranch}`],
    opts.cacheDir
  );
  // Prune any local feature branches from prior applies.
  const branches = execGit(["branch", "--list"], opts.cacheDir)
    .split("\n")
    .map((b) => b.replace(/^[* ]+/, "").trim())
    .filter((b) => b && b !== opts.baseBranch);
  for (const b of branches) {
    try {
      execGit(["branch", "-D", b], opts.cacheDir);
    } catch {
      // ignore
    }
  }
}

interface CreatePrInput {
  repo: RepoRef;
  token: string;
  branch: string;
  baseBranch: string;
  title: string;
  body: string;
  draft: boolean;
  apiBase: string;
}

async function createPullRequest(input: CreatePrInput): Promise<string> {
  const url = `${input.apiBase}/repos/${input.repo.owner}/${input.repo.name}/pulls`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${input.token}`,
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      title: input.title,
      body: input.body,
      head: input.branch,
      base: input.baseBranch,
      draft: input.draft,
    }),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(
      `GitHub API failed creating PR: ${res.status} ${res.statusText} — ${text}`
    );
  }
  const data = (await res.json()) as { html_url?: string };
  if (!data.html_url) {
    throw new Error(`GitHub API returned no html_url: ${JSON.stringify(data)}`);
  }
  return data.html_url;
}

/**
 * Apply a proposal end-to-end against the GitHub repo:
 *   1. Ensure the cache clone is fresh on `baseBranch`.
 *   2. Create a feature branch, replace the snippet exactly once, commit.
 *   3. Push the branch using the token (no token persisted to disk).
 *   4. Open a PR via the GitHub REST API.
 *
 * Throws if:
 *  - target file is missing in the repo
 *  - `originalSnippet` does not appear exactly once in that file
 *  - git push or the GitHub API rejects the call (bad token, permissions, etc.)
 *
 * The caller is responsible for any "did the user actually approve this?"
 * check before invoking — this function does not validate intent.
 */
export async function applyProposal(
  proposal: Proposal,
  opts: ApplyOptions
): Promise<ApplyResult> {
  const baseBranch = opts.baseBranch ?? "main";
  ensureClone({
    repo: opts.repo,
    token: opts.token,
    cacheDir: opts.cacheDir,
    baseBranch,
  });

  const root = path.resolve(opts.cacheDir);
  const absFile = path.resolve(root, proposal.file);
  if (!absFile.startsWith(root + path.sep) && absFile !== root) {
    throw new Error(`Invalid file path: ${proposal.file}`);
  }
  if (!fs.existsSync(absFile)) {
    throw new Error(`File not found in ${opts.repo.owner}/${opts.repo.name}: ${proposal.file}`);
  }

  let content = fs.readFileSync(absFile, "utf-8");
  const occurrences = content.split(proposal.originalSnippet).length - 1;
  if (occurrences !== 1) {
    throw new Error(
      `originalSnippet must appear exactly once in ${proposal.file}, found ${occurrences}`
    );
  }

  const slug =
    proposal.file
      .replace(/[^a-zA-Z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 36) || "edit";
  const prefix = opts.branchPrefix ?? "improvement";
  const branch = `${prefix}/${slug}-${Date.now()}`;
  execGit(["checkout", "-b", branch], root);

  content = content.replace(proposal.originalSnippet, proposal.proposedSnippet);
  fs.writeFileSync(absFile, content, "utf-8");

  execGit(["add", "--", proposal.file], root);

  const reasonLine =
    proposal.reason.split("\n")[0]!.trim().slice(0, 200) || "self-improvement";
  const commitMessage =
    opts.commitMessage ??
    `chore: self-improve — ${proposal.file} — ${reasonLine}`;
  execGit(
    [
      "-c",
      "user.name=self-improving-agent",
      "-c",
      "user.email=self-improving-agent@users.noreply.github.com",
      "commit",
      "-m",
      commitMessage,
    ],
    root
  );
  const commitSha = execGit(["rev-parse", "HEAD"], root).trim();

  execGitWithAuth(
    ["push", "--set-upstream", "origin", branch],
    opts.token,
    root
  );

  const title = opts.prTitle ?? `Self-improve: ${proposal.file}`;
  const body =
    opts.prBody ??
    [
      "Automated proposal from `self-improving-agent`.",
      "",
      `**Risk:** ${proposal.risk}`,
      "",
      "**Reason:**",
      proposal.reason,
      "",
      "**Original (excerpt):**",
      "```",
      proposal.originalSnippet.length > 2_000
        ? proposal.originalSnippet.slice(0, 2_000) + "\n…"
        : proposal.originalSnippet,
      "```",
      "",
      "**Proposed (excerpt):**",
      "```",
      proposal.proposedSnippet.length > 2_000
        ? proposal.proposedSnippet.slice(0, 2_000) + "\n…"
        : proposal.proposedSnippet,
      "```",
    ].join("\n");

  const prUrl = await createPullRequest({
    repo: opts.repo,
    token: opts.token,
    branch,
    baseBranch,
    title,
    body,
    draft: opts.draft !== false,
    apiBase: opts.apiBase ?? "https://api.github.com",
  });

  return { branch, prUrl, commitSha };
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Markdown skill text describing when and how the agent should call the
 * feedback tools. Inject this into your system prompt.
 *
 * Loaded from `skills/feedback.md` so it can be edited without recompiling.
 */
export const feedbackSkill: string = (() => {
  // dist/skill.js → ../skills/feedback.md
  const candidates = [
    path.join(__dirname, "..", "skills", "feedback.md"),
    path.join(__dirname, "..", "..", "skills", "feedback.md"),
  ];
  for (const p of candidates) {
    if (fs.existsSync(p)) return fs.readFileSync(p, "utf-8");
  }
  // Fallback: empty string. Caller can supply their own instructions.
  return "";
})();

import { applyProposal, ensureClone, type ApplyOptions, type ApplyResult } from "./apply.js";
import { resolveConfig, type PartialConfigOpts } from "./env.js";
import {
  loadProposal,
  saveProposal,
  type Proposal,
  type SavedProposal,
} from "./proposal.js";

/**
 * JSON Schema (draft-07 compatible) for `write_improvement_proposal`.
 * Most LLM SDKs accept this shape directly.
 */
export const writeImprovementProposalSchema = {
  type: "object",
  properties: {
    file: {
      type: "string",
      description:
        "Repo-relative path of the file to change, e.g. src/prompts/system.md",
    },
    originalSnippet: {
      type: "string",
      description:
        "Exact contiguous substring from the current file. Must appear exactly once when applied.",
    },
    proposedSnippet: {
      type: "string",
      description: "Replacement text for originalSnippet.",
    },
    reason: {
      type: "string",
      description:
        "1–3 sentences: what failure mode this fixes and why this diff addresses it.",
    },
    risk: {
      type: "string",
      enum: ["low", "medium", "high"],
      description:
        "low = wording/docs · medium = behavior change · high = infra/auth/data.",
    },
  },
  required: ["file", "originalSnippet", "proposedSnippet", "reason", "risk"],
  additionalProperties: false,
} as const;

/** JSON Schema for `apply_proposal`. */
export const applyProposalSchema = {
  type: "object",
  properties: {
    proposalId: {
      type: "string",
      description:
        "The proposalId returned by a prior write_improvement_proposal call.",
    },
    userConfirmedInThisMessage: {
      type: "boolean",
      description:
        "MUST be true. Only set to true if the user's most recent message is an explicit approval (e.g. 'approve', 'yes apply', 'ship it'). Calling with false or without explicit approval is a violation and will be rejected.",
    },
  },
  required: ["proposalId", "userConfirmedInThisMessage"],
  additionalProperties: false,
} as const;

export interface WriteImprovementProposalInput extends Proposal {}

export interface WriteImprovementProposalResult {
  proposalId: string;
  path: string;
  message: string;
}

export interface ApplyProposalInput {
  proposalId: string;
  userConfirmedInThisMessage: boolean;
}

export interface ApplyProposalResult extends ApplyResult {
  proposalId: string;
  message: string;
}

export interface FeedbackToolsContext {
  /** The most recent user message in the conversation, if available. */
  lastUserMessage?: string;
}

export interface FeedbackToolsOptions extends PartialConfigOpts {
  /** Forwarded to `applyProposal` as PR/branch/commit defaults. */
  applyOptions?: Omit<ApplyOptions, "repo" | "token" | "cacheDir" | "baseBranch">;
  /**
   * Optional gate. Throw or return `false` to reject `apply_proposal`.
   * Receives the loaded proposal and the agent-supplied input. Use this
   * to enforce server-side approval policies (matching message intent,
   * checking allowlists, rate-limiting, etc.).
   */
  onBeforeApply?: (
    proposal: SavedProposal,
    input: ApplyProposalInput,
    context: FeedbackToolsContext
  ) => void | boolean | Promise<void | boolean>;
  /**
   * Called after a successful apply. Useful for posting the PR URL back
   * to wherever the user is.
   */
  onApplied?: (
    result: ApplyProposalResult,
    proposal: SavedProposal
  ) => void | Promise<void>;
  /**
   * Called after a successful proposal save. Useful for posting the
   * proposal card back to the user.
   */
  onProposed?: (
    proposal: SavedProposal,
    result: WriteImprovementProposalResult
  ) => void | Promise<void>;
  /**
   * If true (default), kick off a background clone/refresh of the cache
   * when `feedbackTools()` is called so the agent's source is on disk
   * by the time it reads files. Set false to defer until first apply.
   */
  prefetch?: boolean;
}

/** Generic tool definition. Adapt to your framework. */
export interface FeedbackTool<I, O> {
  name: string;
  description: string;
  parameters: object;
  execute: (input: I, context?: FeedbackToolsContext) => Promise<O>;
}

/**
 * Build the two feedback tools.
 *
 * The returned objects are framework-agnostic: `name`, `description`,
 * `parameters` (JSON Schema), and an async `execute(input, context)`.
 *
 * Adapt them to your framework's tool shape — see examples/.
 */
export function feedbackTools(opts: FeedbackToolsOptions = {}): {
  writeImprovementProposal: FeedbackTool<
    WriteImprovementProposalInput,
    WriteImprovementProposalResult
  >;
  applyProposal: FeedbackTool<ApplyProposalInput, ApplyProposalResult>;
} {
  // Lenient resolution at construction so we can bake the cache path /
  // repo into the tool description without crashing if env vars are
  // missing — `apply_proposal` re-resolves strictly at execute time.
  const constructionCfg = resolveConfig({ ...opts, lenient: true });

  // Kick off the clone in the background so the agent can read source
  // files via shell `cat` / a read tool before its first tool call.
  // We swallow errors here — they'll resurface clearly on apply.
  if (opts.prefetch !== false && constructionCfg.token) {
    queueMicrotask(() => {
      try {
        ensureClone({
          repo: constructionCfg.repo,
          token: [REDACTED],
          cacheDir: constructionCfg.cacheDir,
          baseBranch: constructionCfg.baseBranch,
        });
      } catch {
        // Logged on apply if it fails again.
      }
    });
  }

  const repoSlug = `${constructionCfg.repo.owner}/${constructionCfg.repo.name}`;

  const writeImprovementProposal: FeedbackTool<
    WriteImprovementProposalInput,
    WriteImprovementProposalResult
  > = {
    name: "write_improvement_proposal",
    description:
      "Use this when the user is critiquing YOU (your prompts, tools, skills, decisions) and asking you to fix yourself — e.g. \"you keep skipping the setup step\", \"your repro plan is too vague\", \"feedback: rewrite your prompt to handle X\". Do NOT use for normal product work or bug reports unrelated to your own configuration.\n\n" +
      `YOUR OWN SOURCE CODE for the GitHub repo ${repoSlug} is checked out at:\n  ${constructionCfg.cacheDir}\n` +
      "This is a working clone the lib keeps fresh on the base branch — read from it with whatever read tool you have (shell with `cat`/`grep`, a file-reading tool, etc.). The `file` argument below is repo-relative to that path. If the directory doesn't exist yet (first run), the lib will clone it on `apply_proposal`; you can also fetch the file via the GitHub API for `" + repoSlug + "` if you don't want to wait.\n\n" +
      "Workflow:\n" +
      "1. Read the file you intend to change first (don't propose blind).\n" +
      "2. Call this tool with ONE minimal diff: file path (repo-relative), exact originalSnippet (must appear exactly once — copy it verbatim from the file), proposedSnippet, reason, and risk.\n" +
      "3. Write a short reply summarizing the proposal and asking for approval. Do NOT paste the diff as a fenced ```diff``` block in chat in lieu of calling this tool — the tool call IS the proposal; pasting markdown produces no proposalId, no record, and no path to a PR.\n" +
      "4. Wait for explicit approval (\"approve\", \"ship it\", \"lgtm\"). Only then call apply_proposal — never in the same turn as this call.\n\n" +
      "If the snippet appears more than once, expand originalSnippet until unique. One file per proposal — propose multi-file fixes sequentially.",
    parameters: writeImprovementProposalSchema as unknown as object,
    execute: async (input) => {
      const { proposalsDir } = resolveConfig({ ...opts, lenient: true });
      const { proposalId, path } = saveProposal(input, proposalsDir);
      const result: WriteImprovementProposalResult = {
        proposalId,
        path,
        message: `Proposal ${proposalId} saved (risk: ${input.risk}). Show the diff to the user; only call apply_proposal after explicit approval.`,
      };
      if (opts.onProposed) {
        await opts.onProposed({ ...input, proposalId, createdAt: new Date().toISOString() }, result);
      }
      return result;
    },
  };

  const applyProposalTool: FeedbackTool<ApplyProposalInput, ApplyProposalResult> = {
    name: "apply_proposal",
    description:
      `Apply a previously saved proposal against ${repoSlug}: create a branch, commit, push using the configured PAT, and open a draft PR via the GitHub REST API.\n\n` +
      "HARD RULE: Only call this if the user's MOST RECENT message is an unambiguous approval (\"approve\", \"yes apply\", \"ship it\", \"lgtm\"). If the latest message is anything else — a question, a tweak request, silence, ambiguity — do not call this tool, ask instead.\n\n" +
      "Pass userConfirmedInThisMessage: true to acknowledge the approval policy. Setting it to true without explicit approval is a violation and will be rejected.",
    parameters: applyProposalSchema as unknown as object,
    execute: async (input, context) => {
      if (!input.userConfirmedInThisMessage) {
        throw new Error(
          "apply_proposal requires userConfirmedInThisMessage=true. The user must explicitly approve."
        );
      }
      const cfg = resolveConfig(opts);
      const proposal = loadProposal(cfg.proposalsDir, input.proposalId);
      if (opts.onBeforeApply) {
        const ok = await opts.onBeforeApply(proposal, input, context ?? {});
        if (ok === false) {
          throw new Error("apply_proposal rejected by onBeforeApply policy.");
        }
      }
      const applyResult = await applyProposal(proposal, {
        repo: cfg.repo,
        token: cfg.token,
        cacheDir: cfg.cacheDir,
        baseBranch: cfg.baseBranch,
        ...opts.applyOptions,
      });
      const result: ApplyProposalResult = {
        ...applyResult,
        proposalId: input.proposalId,
        message: `Draft PR opened: ${applyResult.prUrl}`,
      };
      if (opts.onApplied) await opts.onApplied(result, proposal);
      return result;
    },
  };

  return {
    writeImprovementProposal,
    applyProposal: applyProposalTool,
  };
}
